CREATE TABLE organization_ai_settings (organization_id uuid PRIMARY KEY REFERENCES organizations(id) ON DELETE CASCADE, enabled boolean NOT NULL DEFAULT false, model text NOT NULL DEFAULT 'gpt-4.1-mini', updated_by_user_id uuid REFERENCES users(id), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ai_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), ticket_id uuid REFERENCES tickets(id) ON DELETE SET NULL, status text NOT NULL CHECK(status IN ('QUEUED','RUNNING','SUCCEEDED','FAILED','CANCELLED')), prompt_version text NOT NULL, redacted_input jsonb NOT NULL, created_by_user_id uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE TABLE ai_results (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL UNIQUE REFERENCES ai_requests(id) ON DELETE CASCADE, organization_id uuid NOT NULL REFERENCES organizations(id), output jsonb NOT NULL, usage jsonb NOT NULL DEFAULT '{}'::jsonb, provider text NOT NULL, model text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid REFERENCES organizations(id), topic text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz);
ALTER TABLE organization_ai_settings ENABLE ROW LEVEL SECURITY; ALTER TABLE ai_requests ENABLE ROW LEVEL SECURITY; ALTER TABLE ai_results ENABLE ROW LEVEL SECURITY; ALTER TABLE outbox_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY ai_settings_tenant ON organization_ai_settings USING(organization_id=app.current_organization_id()) WITH CHECK(organization_id=app.current_organization_id());
CREATE POLICY ai_requests_tenant ON ai_requests USING(organization_id=app.current_organization_id()) WITH CHECK(organization_id=app.current_organization_id());
CREATE POLICY ai_results_tenant ON ai_results USING(organization_id=app.current_organization_id()) WITH CHECK(organization_id=app.current_organization_id());
CREATE POLICY outbox_tenant ON outbox_events USING(organization_id=app.current_organization_id()) WITH CHECK(organization_id=app.current_organization_id());
GRANT SELECT, INSERT, UPDATE ON organization_ai_settings, ai_requests, ai_results, outbox_events TO jupiter_app;
